#!/usr/bin/env python3
"""Model prepared release rows offline; never access credentials or execute SQL."""
import argparse,json,pathlib,collections,math,hashlib
a=argparse.ArgumentParser();a.add_argument('--root',required=True);a.add_argument('--release',required=True);a.add_argument('--capacity-receipt',required=True);a.add_argument('--output',required=True);args=a.parse_args();root=pathlib.Path(args.root).resolve();capacity_path=pathlib.Path(args.capacity_receipt).resolve()
p=pathlib.Path(args.release).resolve();j=json.loads((p/'index.json').read_text());receipt=json.loads(capacity_path.read_text());stats=collections.defaultdict(lambda:{'rows':0,'json_bytes':0,'text_bytes':0,'evidence_bytes':0,'inline_tuple_model_bytes':0,'tuple_below_2048':0,'indexes_model_bytes':0});sizes=[];skipped=[]
enc=lambda v:json.dumps(v,separators=(',',':'),ensure_ascii=False).encode();align=lambda x:(x+7)//8*8
def field(v):
 if v is None:return 0
 if isinstance(v,int):return 8
 b=v.encode()if isinstance(v,str)else enc(v)
 return len(b)+(1 if len(b)<=126 else 4)
for b in j['batches']:
 raw=(p/b['path']).read_bytes()
 if hashlib.sha256(raw).hexdigest()!=b['sha256']:raise ValueError('Prepared batch bytes changed: '+b['path'])
 if b['path'].startswith('1-')or b['path']=='release-1.json':skipped.append({'path':b['path'],'bytes':len(raw)});continue
 data=json.loads(raw);sizes.append(len(raw))
 for kind in ['memberships','changes','entities','sources']:
  for row in data.get(kind,[]):
   s=stats[kind];s['rows']+=1;s['json_bytes']+=len(enc(row));cols=dict(row)
   if kind in ['memberships','changes']:cols.pop('kind',None);cols['release_id']=data['release_id']
   text=sum(len(v.encode())if isinstance(v,str)else len(enc(v))if isinstance(v,(dict,list))else 0 for v in cols.values());s['text_bytes']+=text;s['evidence_bytes']+=len(enc(row.get('evidence',{})));tuplemodel=align(24+sum(field(v)for v in cols.values()))+4;s['inline_tuple_model_bytes']+=tuplemodel;s['tuple_below_2048']+=int(tuplemodel<=2048)
   if kind=='memberships':indexes=[['release_id','entity_id'],['release_id','active','parent_id','entity_id'],['release_id','active','entity_id']]
   elif kind=='changes':indexes=[['id'],['release_id','id'],['old_entity_id','release_id']]
   else:indexes=[]
