result={'version':1,'read_only':True,'release_id':j['releases'][-1]['id'],'release_sha256':hashlib.sha256((p/'release-4.json').read_bytes()).hexdigest(),'live_snapshot_revision':receipt['snapshot_marker']['revision'],'capacity_receipt_sha256':hashlib.sha256(capacity_path.read_bytes()).hexdigest(),'stats':dict(stats),'reviewed_payload_bytes':sum(sizes),'published_baseline_skipped_bytes':sum(s['bytes']for s in skipped),'published_baseline_skipped_batches':len(skipped),'new_database_rows':{'memberships':stats['memberships']['rows'],'changes':stats['changes']['rows'],'geographic_releases':sum(r['id']not in {x['id']for x in prior['releases']}for r in j['releases']),'stable_entities':stats['entities']['rows'],'sources':sum(s['id']not in knownsource for s in sources),'ingestions_up_to':len(sizes)},'duplicate_rules':{'published_baseline':'bootstrap validates exact hashes/counts then skips version1 staging and rows','existing_entity_ids':'Only42 new entity identities are sent; all84,831 full snapshot memberships are genuinely new under new release key, even for old entity IDs','changes':'New IDs contain new release hash; previous migration change relations get new immutable change rows in release4','sources':'Retained source replays by stable ID; one review source uses new release hash','ingestions':'New bounded batch IDs are append-only receipts; completed retries are idempotent; source journal may be new even when one source row already exists'},'configured_database_budget_bytes':db['configured_budget_bytes'],'observed_database_bytes':db['bytes'],'configured_headroom_bytes':headroom,'budget_is_verified_provider_quota':False,'heap_plus_btree_model_bytes':sum(s['heap_model_with_page_packing']+s['btree_model_90pct_leaf']for s in stats.values()),'fit_proven':False,'assessment':'Payload is not a physical DB measurement, but it credibly understates rather than proves storage fit: membership text alone exceeds configured headroom, and99.49% of modeled membership tuples fall below normal2KiB TOAST threshold. Do not assume archive/gzip/network compression makes TEXT tables small. Current full snapshot release representation is unlikely to fit512MiB budget.','assumptions':['Text storage from postgres/schema.sql; short/ordinary field headers1/4bytes, aligned24byte tuple header+4byte line pointer, activeBIGINT; crude heap packing95% and B-tree leaf fill90%, no WAL/memory/provider accounting','Model does not claim exact TOAST compression, B-tree suffix truncation/dedup, existing page free space, heap bloat, alignment between individualfields or indexinternalpage overhead','Membership fields add release_id and remove transport-onlykind before modeling; max84,396/84,831 below2048model rows do not justify assuming TOAST storage','Source/archive media bodies go to R2, not database; existing preflight148,085,814 registered media bytes are NOT included as binary content in481MB DB. New R2 evidence still adds small metadata/ingestion rows and needs separatehosting limits'],'safest_gate':['Re-read existing /api/storage/capacity and /api/storage/v2/export-marker before import. No SQL writes under this assessment.','Measure physical per-table/TOAST/index stats with authorized existing read-only runtime/admin database path; no new arbitrary-SQL API','Verify actual Neon project-plan storage capacity before committing to staged imports. The env budget is a guardrail, not providerquota, and changing it alone creates no capacity','If verified budget/headroom cannot accommodate realistic growth plusmargin, preserve ready offlinecandidate and report publicationblocked; do not write80krows then discoverbudget exhaustion','No repartitioning/compaction/R2database migration implemented here. Those belong to separately authorized engineering storage work.'],'sql_read_only':['SELECT pg_database_size(current_database()) AS database_bytes;','SELECT n.nspname,c.relname,c.reltuples::bigint AS estimated_rows,pg_relation_size(c.oid) AS heap_main_bytes,pg_table_size(c.oid) AS heap_and_toast_bytes,pg_indexes_size(c.oid) AS index_bytes,pg_total_relation_size(c.oid) AS total_bytes FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=\'public\' AND c.relname IN (\'atlas_geographic_memberships\',\'atlas_geographic_changes\',\'atlas_entities\',\'atlas_ingestions\',\'atlas_sources\',\'atlas_geographic_releases\') ORDER BY c.relname;','SELECT release_id,count(*) AS rows,sum(octet_length(evidence)) AS uncompressed_evidence_bytes,sum(pg_column_size(evidence)) AS evidence_stored_datum_bytes,avg(pg_column_size(evidence)) AS average_evidence_datum_bytes FROM atlas_geographic_memberships GROUP BY release_id ORDER BY release_id;','SELECT indexname,indexdef FROM pg_indexes WHERE schemaname=\'public\' AND tablename IN (\'atlas_geographic_memberships\',\'atlas_geographic_changes\');']}
pathlib.Path(args.output).write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'assessment':result['assessment'],'new_rows':result['new_database_rows'],'headroom':headroom,'heap_plus_btree_model_bytes':result['heap_plus_btree_model_bytes']}))
